<?php declare(strict_types=1);
try{
    $annualPostingText=static fn(string $text):string=>\Kulturhus\Native\Language\BalanceFilingMessages::text($text,$managerLanguageMessages??[]);
    $annualPostingReader=new \Kulturhus\Verein\BalancePostingOriginalRead($db,(string)$_SESSION['actor']);$annualPostingSaved=$annualPostingReader->get(input($_GET,'balance_year'),input($_GET,'annual_posting'),input($_GET,'annual_posting_sha256'));$annualPostingRow=$annualPostingSaved['posting'];$annualPostingCurrent=$annualPostingSaved['current'];$annualPostingAt=(new DateTimeImmutable($annualPostingRow['created_at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i');
}catch(DomainException $error){if(!headers_sent())http_response_code(in_array($error->getCode(),[403,404,409,422,503],true)?$error->getCode():422);echo '<p role="alert">'.e($annualPostingText($error->getMessage())).'</p>';return;}
$annualPostingMoney=static fn(int $cents):string=>number_format($cents/100,2,',','.').' €';
?>
<link rel="stylesheet" href="tax-guided.css?v=3"><div class="content" data-tax-guided>
<div class="page-heading"><h1><?= e($annualPostingText($annualPostingRow['reversal_of']===null?'Gespeicherte Buchung':'Gespeicherte Gegenbuchung')) ?></h1></div><p><?= e((string)$annualPostingSaved['year']) ?></p>
<section class="card" data-annual-posting-original="<?= e($annualPostingSaved['sha256']) ?>"><p role="status"><?= e($annualPostingText('Diese Buchung ist bereits gespeichert. Das Öffnen bestätigt keinen neuen Buchungsauftrag.')) ?></p><h2><?= e($annualPostingRow['description']) ?></h2>
<dl><dt><?= e($annualPostingText('Buchungsdatum')) ?></dt><dd><?= e(dateDe($annualPostingRow['booked_on'])) ?></dd><dt><?= e($annualPostingText('Gespeichert am')) ?></dt><dd><?= e($annualPostingAt) ?></dd><dt><?= e($annualPostingText('Beleg / Nachweis')) ?></dt><dd><?= e($annualPostingRow['evidence']) ?></dd></dl>
<?php foreach($annualPostingRow['lines']as$annualPostingLine): ?><article><h3><?= e($annualPostingCurrent['accounts'][$annualPostingLine['account']]['name']) ?></h3><dl><dt><?= e($annualPostingText('Soll')) ?></dt><dd><?= e($annualPostingMoney($annualPostingLine['debit_cents'])) ?></dd><dt><?= e($annualPostingText('Haben')) ?></dt><dd><?= e($annualPostingMoney($annualPostingLine['credit_cents'])) ?></dd><?php if($annualPostingLine['sphere']!==''): ?><dt><?= e($annualPostingText('Vereinsbereich')) ?></dt><dd><?= e($annualPostingText(\Kulturhus\Verein\TaxCatalog::SPHERES[$annualPostingLine['sphere']]??$annualPostingLine['sphere'])) ?></dd><?php endif ?></dl></article><?php endforeach ?>
<?php if($annualPostingRow['reversal_of']!==null):$annualPostingBase=null;foreach($annualPostingCurrent['entries']as$annualEntry)if($annualEntry['id']===$annualPostingRow['reversal_of'])$annualPostingBase=$annualEntry; ?><p><?= e($annualPostingText('Diese Gegenbuchung gehört zur gespeicherten ursprünglichen Buchung.')) ?><?= $annualPostingBase!==null?' '.e($annualPostingBase['description']):'' ?></p><?php endif ?></section>
<section class="card" data-annual-posting-current><h2><?= e($annualPostingText('Aktueller Jahresstand')) ?></h2><p><?= e($annualPostingText($annualPostingCurrent['state']==='closed'?'Buchungsstand festgeschrieben':'Buchungsstand offen')) ?></p><p><?= e($annualPostingText('Ergebnis dieses Zeitraums').': '.$annualPostingMoney($annualPostingCurrent['calculation']['annual_result_cents'])) ?></p><?php foreach($annualPostingCurrent['entries']as$annualPostingRelated)if($annualPostingRelated['reversal_of']===$annualPostingRow['id']): ?><div data-annual-posting-current-reversal="<?= e($annualPostingRelated['id']) ?>"><p><strong><?= e($annualPostingText('Zu dieser Buchung ist eine Gegenbuchung gespeichert.')) ?></strong></p><p><?= e($annualPostingText('Gegenbuchung vom').' '.dateDe($annualPostingRelated['date'])) ?></p><p><?= e($annualPostingRelated['evidence']) ?></p></div><?php endif ?></section>
<p><a class="btn btn-outline" data-annual-posting-current-link href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$annualPostingSaved['year']])) ?>"><?= e($annualPostingText('Aktuellen Jahresstand öffnen')) ?></a></p></div>
